t_context', true), '')::jsonb ->> 'targetEntityId' = 'group-membership' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'operation' = 'create' AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb -> 'fields' = '["household","person","relationship","valid-from"]'::jsonb AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'activePackageRevision' = NULLIF(current_setting('registry.active_package_revision', true), '') AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'targetRecordId' = "record_id"::text AND NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb -> 'phase' = '{"kind":"review","stage":"final-approval"}'::jsonb AND NULLIF(current_setting('registry.access_profile', true), '') = 'household-contact-supervisor' AND NULLIF(current_setting('registry.principal', true), '') IS NOT NULL AND NULLIF(current_setting('registry.purpose', true), '') IN ('household-contact-review') AND (NULLIF(current_setting('registry.change_request_target_context', true), '')::jsonb ->> 'expectedRevision') IS NULL
         AND EXISTS (
